#include "opensim/scene/task_inventory_file.hpp"
#include <iostream>
using namespace opensim;using namespace scene;
namespace {
framework::Uuid id(int n){auto s=std::to_string(n);return framework::Uuid("11223344-5566-7788-99aa-"+std::string(12-s.size(),'0')+s);}
std::string hex(std::span<const std::uint8_t> bytes){std::string out;constexpr char d[]="0123456789abcdef";for(auto b:bytes){out+=d[b>>4];out+=d[b&15];}return out;}
TaskInventoryFileItem item(int type,int inv,std::uint32_t permissions,int scenario){TaskInventoryFileItem i;i.item=id(2);i.asset=id(3);i.creator=id(4);i.last_owner=id(5);i.owner=id(6);i.group=id(7);if(scenario&1)i.owner=i.group;i.creation_date=0xffffffffu;i.flags=0xabcdef01u;i.base_permissions=0xfedcba98u;i.current_permissions=permissions;i.group_permissions=0x1234u;i.everyone_permissions=0x80000000u;i.next_permissions=0x7fffffffu;i.type=type;i.inventory_type=inv;i.name="Script";i.description="Description";if(scenario&2){i.name="名|🙂\n";i.description="雪\t<&>";}if(scenario&4)i.name=std::string("a\0b",3);return i;}
std::string probe(int type,int inv,std::uint32_t permissions,int scenario){std::vector<std::string> events;int step=0,random=0;bool edit=true;TaskInventoryFileBackend backend;backend.can_edit_inventory=[&](auto part,auto agent){events.push_back("P:"+part.str()+":"+agent.str());if((scenario&16)&&step==2)throw std::runtime_error("permission");return edit;};backend.random_uuid=[&]{auto value=id(800+(++random));events.push_back("G:"+value.str());if((scenario&32)&&step==0)throw std::runtime_error("random");return value;};backend.add_file=[&](const auto& name,auto data){events.push_back("F:"+name+":"+hex(*data));if((scenario&8)&&step==0)throw std::runtime_error("add");return !(scenario&128);};backend.reply=[&](auto part,int16_t serial,auto name){events.push_back("R:"+part.str()+":"+std::to_string(serial)+":"+hex(name));if((scenario&64)&&step==0)throw std::runtime_error("reply");};TaskInventoryFile cache(id(1),std::move(backend));std::string status;
 for(step=0;step<11;++step){std::uint32_t serial=step==4?0:step<5?1:step==5?65535:step<9?65536:65537;edit=step!=2;bool god=step==3;std::vector<TaskInventoryFileItem> items;if(step!=7)items.push_back(item(step>=9?-1:type,inv,permissions,scenario));try{cache.request(id(9),serial,items,god);status+='O';}catch(const std::out_of_range&){status+='B';}catch(const std::exception&){status+='E';}}
 for(const auto& event:events){status+='|';status+=event;}return status;}
int checks=0;void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}
void run(){auto valid=probe(10,10,0xc000u,0);check(valid.starts_with("OOOOOOOOOBO"),"source cache reuse survives type-generation failure");check(valid.find("R:"+id(1).str()+":-1:")!=valid.npos,"serial65535 wraps to signed short");check(valid.find("R:"+id(1).str()+":0:")!=valid.npos,"empty and wrapped serial replies");auto denied=probe(10,10,0,0);check(denied.find(hex(std::span<const uint8_t>(reinterpret_cast<const uint8_t*>("asset_id\t00000000-0000-0000-0000-000000000000"),45)))!=denied.npos,"script asset hidden without Modify and Copy");check(probe(-1,10,0xc000u,0).starts_with("BBBBOBBOBBB"),"SDK invalid type index preserved");}
}
int main(int argc,char**argv){try{if(argc==2&&std::string_view(argv[1])=="--probe"){int type,inv,scenario;std::uint32_t mask;while(std::cin>>type>>inv>>mask>>scenario)std::cout<<probe(type,inv,mask,scenario)<<'\n';return 0;}run();std::cout<<"PASS: "<<checks<<" task inventory file checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
